// GENERATED by scripts/sync-shared.mjs from app/src/observations/schema.ts. Do not edit here.
// PRD P15 — Observations v1: signed, slot-anchored market observations any agent can publish, query and verify.
// Pure and platform-free (shared by the web Functions and the SDK via sync-shared). Signing / signature
// verification live in the host (WebCrypto in Functions, @noble/curves in the SDK); this module owns the
// schema, canonical bytes, ids, freshness and aggregation.
import { sha256 } from '@noble/hashes/sha2.js'
import { bytesToHex, utf8ToBytes } from '@noble/hashes/utils.js'

export const OBSERVATION_VERSION = 1 as const
export const OBSERVATION_KINDS = ['price', 'liquidity', 'volume24h', 'holders', 'risk', 'route'] as const
export type ObservationKind = (typeof OBSERVATION_KINDS)[number]
export const OBSERVATION_UNITS: Record<ObservationKind, string[]> = {
  price: ['usd'], liquidity: ['usd'], volume24h: ['usd'], holders: ['count'], risk: ['level'], route: ['bps'],
}
export const MAX_SKEW_MS = 10 * 60_000 // observedAt must be within ±10 minutes of the indexer's clock
export const MIN_TTL_SEC = 10
export const MAX_TTL_SEC = 86_400
export const DEFAULT_TTL_SEC = 300
export const RATE_LIMIT_PER_HOUR = 120

/** What the publisher signs. Keys are sorted in the canonical form; `note` is optional. */
export interface ObservationBody {
  v: 1
  kind: ObservationKind
  mint: string
  value: number
  unit: string
  source: string // e.g. "jupiter-price-v3", "geckoterminal", "my-bot/1.2"
  slot: number // Solana slot the observation is anchored to
  observedAt: number // unix ms
  ttlSec: number
  publisher: string // base58 pubkey
  note?: string
}

export interface Observation extends ObservationBody {
  id: string // sha256(canonical)[0..32]
  sig: string // base58 Ed25519 signature over the canonical bytes
}

const BASE58 = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/
const SIG58 = /^[1-9A-HJ-NP-Za-km-z]{80,90}$/

/** Deterministic JSON: sorted keys, no whitespace, no undefined. */
export function canonical(body: ObservationBody): string {
  const keys = (Object.keys(body) as (keyof ObservationBody)[]).filter((k) => body[k] !== undefined).sort()
  return '{' + keys.map((k) => `${JSON.stringify(k)}:${JSON.stringify(body[k])}`).join(',') + '}'
}

export const canonicalBytes = (body: ObservationBody) => utf8ToBytes(canonical(body))
export const observationId = (body: ObservationBody) => bytesToHex(sha256(canonicalBytes(body))).slice(0, 32)

export type Validation = { ok: true; body: ObservationBody } | { ok: false; error: string }

/** Schema and clock checks (no signature). `now` defaults to Date.now(). */
export function validateObservation(input: unknown, now = Date.now()): Validation {
  const o = input as Partial<Observation> | null
  if (!o || typeof o !== 'object') return { ok: false, error: 'Observation must be an object.' }
  if (o.v !== 1) return { ok: false, error: 'Unsupported observation version (expected v: 1).' }
  if (!OBSERVATION_KINDS.includes(o.kind as ObservationKind)) return { ok: false, error: `kind must be one of ${OBSERVATION_KINDS.join(', ')}.` }
  if (typeof o.mint !== 'string' || !BASE58.test(o.mint)) return { ok: false, error: 'mint must be a base58 address.' }
  if (typeof o.value !== 'number' || !Number.isFinite(o.value)) return { ok: false, error: 'value must be a finite number.' }
  if (typeof o.unit !== 'string' || !OBSERVATION_UNITS[o.kind as ObservationKind].includes(o.unit)) return { ok: false, error: `unit for ${o.kind} must be ${OBSERVATION_UNITS[o.kind as ObservationKind].join(' | ')}.` }
  if (typeof o.source !== 'string' || o.source.length < 1 || o.source.length > 64) return { ok: false, error: 'source must be 1–64 characters.' }
  if (!Number.isInteger(o.slot) || (o.slot as number) <= 0) return { ok: false, error: 'slot must be a positive integer.' }
  if (typeof o.observedAt !== 'number' || Math.abs(now - o.observedAt) > MAX_SKEW_MS) return { ok: false, error: 'observedAt must be within 10 minutes of now (unix ms).' }
  if (!Number.isInteger(o.ttlSec) || (o.ttlSec as number) < MIN_TTL_SEC || (o.ttlSec as number) > MAX_TTL_SEC) return { ok: false, error: `ttlSec must be an integer between ${MIN_TTL_SEC} and ${MAX_TTL_SEC}.` }
  if (typeof o.publisher !== 'string' || !BASE58.test(o.publisher)) return { ok: false, error: 'publisher must be a base58 address.' }
  if (o.note !== undefined && (typeof o.note !== 'string' || o.note.length > 280)) return { ok: false, error: 'note must be at most 280 characters.' }
  const body: ObservationBody = { v: 1, kind: o.kind as ObservationKind, mint: o.mint, value: o.value, unit: o.unit, source: o.source, slot: o.slot as number, observedAt: o.observedAt, ttlSec: o.ttlSec as number, publisher: o.publisher, ...(o.note !== undefined ? { note: o.note } : {}) }
  return { ok: true, body }
}

/** Shape checks for a signed observation: body valid, id matches, signature present (not verified here). */
export function validateSigned(input: unknown, now = Date.now()): { ok: true; obs: Observation } | { ok: false; error: string } {
  const v = validateObservation(input, now)
  if (!v.ok) return v
  const o = input as Partial<Observation>
  if (typeof o.sig !== 'string' || !SIG58.test(o.sig)) return { ok: false, error: 'sig must be a base58 Ed25519 signature.' }
  const id = observationId(v.body)
  if (o.id !== undefined && o.id !== id) return { ok: false, error: 'id does not match the canonical body.' }
  return { ok: true, obs: { ...v.body, id, sig: o.sig } }
}

export const expiresAt = (o: ObservationBody) => o.observedAt + o.ttlSec * 1000
export const isFresh = (o: ObservationBody, now = Date.now()) => expiresAt(o) > now

export interface Aggregate {
  kind: ObservationKind
  mint: string
  count: number // fresh observations
  publishers: number // distinct publishers (one value each: their latest)
  median: number | null
  min: number | null
  max: number | null
  latestAt: number | null
  spreadPct: number | null // (max − min) / median
}

/** Median over the latest fresh observation of each publisher for one (kind, mint). */
export function aggregate(observations: ObservationBody[], kind: ObservationKind, mint: string, now = Date.now()): Aggregate {
  const fresh = observations.filter((o) => o.kind === kind && o.mint === mint && isFresh(o, now))
  const latest = new Map<string, ObservationBody>()
  for (const o of fresh) { const cur = latest.get(o.publisher); if (!cur || o.observedAt > cur.observedAt) latest.set(o.publisher, o) }
  const values = [...latest.values()].map((o) => o.value).sort((a, b) => a - b)
  const n = values.length
  const median = n ? (n % 2 ? values[(n - 1) / 2] : (values[n / 2 - 1] + values[n / 2]) / 2) : null
  return {
    kind, mint, count: fresh.length, publishers: n, median, min: n ? values[0] : null, max: n ? values[n - 1] : null,
    latestAt: fresh.length ? Math.max(...fresh.map((o) => o.observedAt)) : null,
    spreadPct: median ? ((values[n - 1] - values[0]) / median) * 100 : null,
  }
}

/** PRD P12.8 (Season 2) — publisher shares of the observations budget, weighted by verified consumption:
 *  each publisher counts the distinct consumers of its observations; shares are normalised to 1. */
export function publisherShares(consumptions: { publisher: string; consumer: string }[]): Record<string, number> {
  const consumers = new Map<string, Set<string>>()
  for (const c of consumptions) { if (c.publisher === c.consumer) continue; (consumers.get(c.publisher) ?? consumers.set(c.publisher, new Set()).get(c.publisher)!).add(c.consumer) }
  const total = [...consumers.values()].reduce((s, set) => s + set.size, 0)
  if (!total) return {}
  return Object.fromEntries([...consumers.entries()].map(([p, set]) => [p, set.size / total]))
}

/** Message a consumer signs to prove it used an observation (the indexer verifies with the consumer's key). */
export const consumeMessage = (observationId: string, consumer: string, ts: number) => JSON.stringify({ wallet: consumer, ts, action: 'consume', observationId })
